package com.pranit.productsupport.core.service;
import static org.junit.jupiter.api.Assertions.*;import com.pranit.productsupport.contracts.CreateTicketRequest;import com.pranit.productsupport.contracts.TicketPriority;import org.junit.jupiter.api.Test;
class RequestHashTest {@Test void equivalentInputProducesStableHash(){var a=new CreateTicketRequest(9L,"screen defect",TicketPriority.HIGH);var b=new CreateTicketRequest(9L," screen defect ",TicketPriority.HIGH);assertEquals(RequestHash.ticket(1L,a),RequestHash.ticket(1L,b));}@Test void hashIsScopedToUserAndPayload(){var r=new CreateTicketRequest(9L,"screen defect",TicketPriority.HIGH);assertNotEquals(RequestHash.ticket(1L,r),RequestHash.ticket(2L,r));assertNotEquals(RequestHash.ticket(1L,r),RequestHash.ticket(1L,new CreateTicketRequest(10L,"screen defect",TicketPriority.HIGH)));}}
